// ========================================================================
// DOWNLOAD JSON (for npoint.io)
// ========================================================================
function downloadJSON() {
    // Build the JSON data structure from the CSV data
    var sections = {};
    var sectionOrder = [];

    for (var i = 0; i < CSV_ROWS.length; i++) {
        var row = CSV_ROWS[i];
        var secId = row[0];
        var secName = row[1];
        var catId = row[2];
        var catName = row[3];
        var taskId = row[4];
        var taskName = row[5];
        var priority = row[6];
        var note = row[7];

        if (!sections[secId]) {
            sections[secId] = {
                id: secId,
                name: secName,
                description: secId === 1 ? 'Phần mềm quản trị đào tạo - Training Management System' : 'Hệ thống thi trắc nghiệm trực tuyến - Online Exam System',
                color: secId === 1 ? 'blue' : 'purple',
                categories: []
            };
            sectionOrder.push(secId);
        }

        // Check if category already exists
        var catExists = false;
        for (var c = 0; c < sections[secId].categories.length; c++) {
            if (sections[secId].categories[c].id === catId) {
                catExists = true;
                if (taskId && taskName) {
                    sections[secId].categories[c].tasks.push({
                        id: taskId,
                        name: taskName,
                        priority: priority || 'normal'
                    });
                } else if (note && !taskId) {
                    sections[secId].categories[c].note = note;
                }
                break;
            }
        }

        if (!catExists) {
            var newCat = {
                id: catId,
                name: catName,
                note: note || null,
                tasks: []
            };
            if (taskId && taskName) {
                newCat.tasks.push({
                    id: taskId,
                    name: taskName,
                    priority: priority || 'normal'
                });
            }
            sections[secId].categories.push(newCat);
        }
    }

    var sectionsArray = [];
    for (var s = 0; s < sectionOrder.length; s++) {
        sectionsArray.push(sections[sectionOrder[s]]);
    }

    var jsonData = {
        project: {
            name: 'Bảo trì phần mềm quản lý đào tạo',
            shortName: 'HATINH',
            contractDate: '25/03/2026',
            version: '1.0'
        },
        sections: sectionsArray
    };

    var jsonStr = JSON.stringify(jsonData, null, 2);
    var blob = new Blob([jsonStr], { type: 'application/json;charset=utf-8;' });
    var link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'data-baotri-hatinh.json';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(link.href);
    showDLStatus();
}

