    for (var s = 0; s < sectionOrder.length; s++) {
        sectionsArray.push(sections[sectionOrder[s]]);
    }

    var jsonData = {
        project: { name: 'Bảo trì phần mềm quản lý đào tạo', shortName: 'HATINH', contractDate: '25/03/2026', version: '1.0' },
        sections: sectionsArray
    };

    var blob = new Blob([JSON.stringify(jsonData, null, 2)], { type: 'application/json;charset=utf-8;' });
    var link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'data-baotri-hatinh.json';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(link.href);
    showDLStatus();
}

function showDLStatus() {
    var el = document.getElementById('dlStatus');
    if (el) { el.classList.remove('hidden'); setTimeout(function() { el.classList.add('hidden'); }, 3000); }
}

